-- Replace target_chats with auto/moto channel database (188 channels)
-- Run: psql $DATABASE_URL -f app/database/migrations/011_replace_target_chats.sql

BEGIN;

-- 1. Deactivate old channels (keeps history in posts/comments)
UPDATE target_chats SET is_active = false, updated_at = now() WHERE chat_url NOT LIKE 'id:%';

-- 2. Clear join status for deactivated channels so accounts re-join on --join
DELETE FROM account_chats
WHERE chat_id IN (
    SELECT id FROM target_chats WHERE is_active = false AND chat_url NOT LIKE 'id:%'
);

-- 3. Insert / reactivate new channel list

COMMIT;
